const d=$json;
const ruc=d.ruc ?? $('Revisar formato del RUC').first().json.ruc;
const escape=s=>String(s??'No disponible').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let titulo, mensaje;
if(d.resultado==='FORMATO_INVALIDO'){
 titulo='Revisa el RUC';
 mensaje='Escribe exactamente 11 dígitos, sin letras ni guiones. No se consultó el padrón.';
}else if(d.resultado==='ENCONTRADO'){
 titulo='RUC encontrado en el padrón';
 mensaje='RUC: '+escape(ruc)+'<br>Razón social: '+escape(d.razonSocial)+'<br>Estado: '+escape(d.estado)+'<br>Condición: '+escape(d.condicion)+'<br>Ubigeo: '+escape(d.ubigeo);
}else if(d.resultado==='NO_ENCONTRADO'){
 titulo='RUC no encontrado en esta copia';
 mensaje='El RUC '+escape(ruc)+' no aparece en el padrón consultado. Revisa el número y confirma en SUNAT; esto no demuestra que la empresa no exista.';
}else{
 titulo='No se pudo consultar el padrón';
 mensaje='La fuente local no está disponible o la consulta falló. Intenta nuevamente cuando el servicio y la carga del padrón estén listos. No se ha determinado si el RUC existe.';
}
if(['ENCONTRADO','NO_ENCONTRADO'].includes(d.resultado)){
 mensaje+='<br><br>Fecha del padrón: '+escape(d.fechaPadron)+'<br>Consulta: '+escape(d.fechaConsulta)+'<br>Fuente: padrón reducido de SUNAT. Datos de una copia, no en tiempo real.<br>Esta consulta no verifica el RNP ni determina si puedes participar en una contratación.';
}
return [{json:{...d,ruc,resultado:d.resultado??'ERROR_CONSULTA',titulo,mensaje}}];
